class Solution {
  public int longestPalindrome(String s, String t) {
    int n = s.length(), m = t.length();
    boolean[][] ps = new boolean[n][n], pt = new boolean[m][m];
    int[] startS = new int[n + 1], endT = new int[m];
    for (int i = n - 1; i >= 0; i--) {
      for (int j = i; j < n; j++) {
        ps[i][j] = s.charAt(i) == s.charAt(j) && (j - i < 2 || ps[i + 1][j - 1]);
        if (ps[i][j]) startS[i] = Math.max(startS[i], j - i + 1);
      }
    }
    for (int i = m - 1; i >= 0; i--) {
      for (int j = i; j < m; j++) {
        pt[i][j] = t.charAt(i) == t.charAt(j) && (j - i < 2 || pt[i + 1][j - 1]);
        if (pt[i][j]) endT[j] = Math.max(endT[j], j - i + 1);
      }
    }
    int[] next = new int[m + 1], cur = new int[m + 1];
    int ans = 0;
    for (int i = n; i >= 0; i--) {
      for (int j = 0; j <= m; j++) {
        int best = Math.max(i < n ? startS[i] : 0, j > 0 ? endT[j - 1] : 0);
        if (i < n && j > 0 && s.charAt(i) == t.charAt(j - 1))
          best = Math.max(best, 2 + next[j - 1]);
        cur[j] = best;
        ans = Math.max(ans, best);
      }
      int[] tmp = next;
      next = cur;
      cur = tmp;
    }
    return ans;
  }
}
